<script lang="ts">
  export let onClick: () => void = () => {};
  export let isActive: boolean = false;
  
  function handleKeyPress(event: KeyboardEvent) {
    if (event.key === 'Enter' || event.key === ' ') {
      onClick();
    }
  }
</script>

