<style>
  :global(*) {
    box-sizing: border-box;
  }

  .choose-button {
    height: 47px;
    padding: 10px 20px;
    background: #53BD4E;
    box-shadow: 0px 4px 0px rgba(0, 0, 0, 0.25);
    border-radius: 8px;
    justify-content: center;
    align-items: center;
    gap: 25px;
    display: inline-flex;
    cursor: pointer;
    /* transition: all 0.2s ease; */
    user-select: none;
  }

  .choose-button.active {
    background: #F3F3F3;
  }

  .choose-button:hover:not(.active) {
    background: #4AA945;
  }

  .choose-button.active:hover {
    background: #DFDFDF;
  }

  .choose-button:active:not(.active) {
    background: #4AA945;
    box-shadow: 0px 4px 0px #99D4CE inset;
    padding-top: 14px;
    padding-bottom: 6px;
  }

  .choose-button.active:active {
    background: #DFDFDF;
    box-shadow: 0px 4px 0px #DFDFDF;
    padding-top: 14px;
    padding-bottom: 6px;
  }

  .text {
    text-align: center;
    justify-content: center;
    display: flex;
    flex-direction: column;
  }

  .text span {
    font-size: 30px;
    font-family: 'Comic Neue', sans-serif;
    font-weight: 700;
    word-wrap: break-word;
    color: white;
  }

  .active .text span {
    color: #444444;
  }
</style>